describe('Maze (recursive backtracker, 15x15)', () => {
  it('is fully connected for seeds 1..10 (BFS reaches all 225 cells)', () => {
    for (let seed = 1; seed <= 10; seed++) {
      const maze = Maze.generateSeeded(W, H, seed);
      const { dist } = maze.bfs(0);
      let reached = 0;
      for (let i = 0; i < dist.length; i++) if (dist[i] !== -1) reached++;
      expect(reached, `seed ${seed}`).toBe(CELLS);
      // Every distance is finite and bounded by cell count.
      expect(Math.max(...dist), `seed ${seed}`).toBeLessThan(CELLS);
    }
  });

  it('is acyclic — exactly w*h - 1 open wall connections for seeds 1..10', () => {
    for (let seed = 1; seed <= 10; seed++) {
      const maze = Maze.generateSeeded(W, H, seed);
      // Count openings on one side only to cross-check the /2 invariant.
      let oneSided = 0;
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          if (maze.isOpen(x, y, DIRS[1])) oneSided++; // east
          if (maze.isOpen(x, y, DIRS[2])) oneSided++; // south
        }
      }
      const openings = maze.countOpenings();
      expect(openings % 2, `seed ${seed}`).toBe(0); // symmetric carving
      expect(openings / 2, `seed ${seed}`).toBe(CELLS - 1);
      expect(openings / 2, `seed ${seed} vs one-sided count`).toBe(oneSided);
    }
  });

  it('is deterministic per seed with a mulberry32 RNG', () => {
    for (let seed = 1; seed <= 10; seed++) {
      const a = Maze.generate(W, H, mulberry32(seed));
      const b = Maze.generate(W, H, mulberry32(seed));
      expect(Buffer.from(a.walls).equals(Buffer.from(b.walls)), `seed ${seed}`)
        .toBe(true);

      // Different seeds produce different carvings.
      let differsFromOtherSeed = false;
      for (let other = 1; other <= 10 && !differsFromOtherSeed; other++) {
        if (other === seed) continue;
        const c = Maze.generateSeeded(W, H, other);
        differsFromOtherSeed = !Buffer.from(a.walls).equals(
          Buffer.from(c.walls),
        );
      }
      expect(differsFromOtherSeed, `seed ${seed} unique among 1..10`).toBe(true);
    }

    // The RNG itself reproduces its sequence.
    const r1 = mulberry32(42);
    const r2 = mulberry32(42);
    for (let i = 0; i < 100; i++) expect(r1()).toBe(r2());
